    result = list(row)

    if test_rule_name == "new_rule_v2":
        """New rule: Process only the FIRST two fg groups.
        For each fg group:
        - If there's a NEXT fg group:
          - Modify some bg cells starting from (group_end + 1) to (next_group_start - 1)
        """
        # Group consecutive FG cells
        groups = []
        current = []
        for i, c in enumerate(fg_cols):
            if i == 0:
                current = [c]
            elif c == fg_cols[i-1] + 1:
                current.append(c)
            else:
                groups.append(current)
                current = [c]
        if current:
            groups.append(current)

        # Process only first 2 groups
        for k in range(min(2, len(groups))):
            group = groups[k]
            group_end = max(group)

            if k < len(groups) - 1:
                # Has next group
                next_group = groups[k + 1]
                next_start = min(next_group)
                # Fill gap
                for c in range(group_end + 1, next_start):
                    if result[c] == bg:
                        result[c] = 2
            else:
                # Last group
                # Fill all bg after it, but only up to some limit?
                last_fg = group_end
                for c in range(last_fg + 1, len(result)):
                    if result[c] == bg:
                        result[c] = 2
                        # Stop at 4th bg after last?
                        break

    elif test_rule_name == "gap_only_large":
        """Only fill gaps that are >= 7 cells?"""
        for i in range(len(fg_cols) - 1):
            gap = [j for j in range(fg_cols[i] + 1, fg_cols[i+1])]
            if len(gap) >= 7:
