def check_port(port):
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.settimeout(1)
        result = s.connect_ex(('127.0.0.1', port))
        if result == 0:
            s.close()
            return True, port
        else:
            s.close()
            return False, port
    except:
        return False, port

# Check typical ARC service ports
