def gap_fill_with_leading_correct(row, fg=1, bg=5, gap_fill_val=2):
    """GAP-FILLING: Fill before first FG block, between FG blocks, and preserve trailing BG."""
    # Find blocks of consecutive FG values
    blocks = []
    i = 0
    while i < len(row):
        if row[i] == fg:
            start = i
            while i < len(row) and row[i] == fg:
                i += 1
            end = i - 1
            blocks.append((start, end))
        else:
            i += 1

    # Fill gaps
    result = list(row)  # Start with TEST input to preserve leading BG if any
    # Before first block (leading fill)
    if blocks and blocks[0][0] > 0:
        for j in range(blocks[0][0]):
            result[j] = gap_fill_val  # Leading fill
    # Between blocks
    for k in range(len(blocks)-1):
        for j in range(blocks[k][1]+1, blocks[k+1][0]):
